export default "import {\n  SceneGridLayout,\n  SceneGridItem,\n  SceneFlexLayout,\n  SceneFlexItem,\n  SceneAppPage,\n  EmbeddedScene,\n  SceneAppPageState,\n  PanelBuilders,\n} from '@grafana/scenes';\nimport { GRID_CELL_HEIGHT } from '@grafana/scenes/src/components/layout/grid/constants';\nimport { getQueryRunnerWithRandomWalkQuery, getEmbeddedSceneDefaults } from './utils';\n\nexport function getGridLayoutTest(defaults: SceneAppPageState): SceneAppPage {\n  return new SceneAppPage({\n    ...defaults,\n    getScene: () => {\n      return new EmbeddedScene({\n        ...getEmbeddedSceneDefaults(),\n        $data: getQueryRunnerWithRandomWalkQuery(),\n        body: new SceneGridLayout({\n          isLazy: true,\n          isDraggable: true,\n          isResizable: true,\n          children: [\n            new SceneGridItem({\n              x: 0,\n              y: 0,\n              width: 12,\n              height: 10,\n              isResizable: true,\n              isDraggable: true,\n              body: PanelBuilders.timeseries()\n                .setTitle('Draggable and resizable')\n                .setOption('legend', { showLegend: false })\n                .build(),\n            }),\n            new SceneGridItem({\n              x: 12,\n              y: 0,\n              width: 12,\n              height: 10,\n              isResizable: false,\n              isDraggable: false,\n              body: PanelBuilders.timeseries()\n                .setTitle('No drag and no resize')\n                .setOption('legend', { showLegend: false })\n                .build(),\n            }),\n            new SceneGridItem({\n              x: 0,\n              y: 11,\n              width: 24,\n              height: 10,\n              isDraggable: false,\n              isResizable: true,\n              body: new SceneFlexLayout({\n                direction: 'column',\n                // Auto 100% height for SceneFlexLayout inside grid is not working, need to make grid item display: flex\n                height: 10 * GRID_CELL_HEIGHT,\n                children: [\n                  new SceneFlexItem({\n                    body: PanelBuilders.timeseries().setTitle('Child of flex layout').build(),\n                  }),\n                  new SceneFlexItem({\n                    body: PanelBuilders.timeseries().setTitle('Child of flex layout').build(),\n                  }),\n                ],\n              }),\n            }),\n          ],\n        }),\n      });\n    },\n  });\n}\n";